class TooSmallException extends Exception {
    TooSmallException(String message) {
        super(message);
    }
}

public class Main {
    static int check(int n) throws TooSmallException {
        if (n < 10) {
            throw new TooSmallException("小さすぎます: " + n);
        }
        return n;
    }

    public static void main(String[] args) {
        int[] values = {15, 10, 9, 0};

        for (int v : values) {
            try {
                System.out.println("OK " + check(v));
            } catch (TooSmallException e) {
                System.out.println("NG " + e.getMessage());
            }
        }
    }
}

class CheckedProblem extends Exception { }
class UncheckedProblem extends RuntimeException { }

public class Main {
    // 検査例外を投げるなら throws が必須
    static void a() throws CheckedProblem {
        throw new CheckedProblem();
    }

    // 非検査例外なら throws は書かなくてよい
    static void b() {
        throw new UncheckedProblem();
    }

    public static void main(String[] args) {
        try {
            a();
        } catch (CheckedProblem e) {
            System.out.println("a() の検査例外を受け止めた");
        }

        // b() は try-catch がなくてもコンパイルできる（実行すると落ちる）
        try {
            b();
        } catch (UncheckedProblem e) {
            System.out.println("b() の非検査例外を受け止めた");
        }
    }
}

