        System.out.println("open " + label);
    }

    void use(int n) {
        if (n == 0) {
            throw new IllegalStateException("使えません");
        }
        System.out.println("処理 " + n);
    }

    @Override
    public void close() {
        System.out.println("close " + label);
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("=== 正常なとき ===");
        try (Resource a = new Resource("A");
             Resource b = new Resource("B")) {
            a.use(1);
            b.use(1);
        }

        System.out.println("=== 例外が起きたとき ===");
        try (Resource a = new Resource("A");
             Resource b = new Resource("B")) {
            a.use(0);
            b.use(1);                 // 実行されない
        } catch (IllegalStateException e) {
            System.out.println("エラー");
        }
    }
}

class Resource implements AutoCloseable {
    private final String label;
    Resource(String label) { this.label = label; System.out.println("open " + label); }
    @Override public void close() { System.out.println("close " + label); }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("--- 昔の書き方 ---");
        Resource r = new Resource("旧");
        try {
            System.out.println("使う");
        } finally {
            r.close();                    // 自分で閉じる
        }

        System.out.println("--- try-with-resources ---");
        try (Resource r2 = new Resource("新")) {
            System.out.println("使う");
        }                                 // 自動で閉じる
    }
}

